const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let pos = 0;

const MOD = 998244353n;

function pw(a, b) {
    let base = a;
    let exponent = b;
    let result = 1n;

    while (exponent > 0n) {
        if ((exponent & 1n) !== 0n) {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exponent /= 2n;
    }

    return result;
}

function inv(a) {
    return pw(a, MOD - 2n);
}

function main() {
    let tt = 1;
    const factorial = new Array(500010).fill(1n);

    for (let i = 2; i <= 500000; i++) {
        factorial[i] = factorial[i - 1] * BigInt(i) % MOD;
    }

    const output = [];

    while (tt-- > 0) {
        const n = input[pos++];
        const k = input[pos++];
        let answer = 0n;

        for (let i = 1; i <= n - k + 1; i++) {
            const count = Math.floor(n / i);

            if (count < k) {
                continue;
            }

            let sum = factorial[count - 1] * inv(factorial[k - 1]) % MOD;
            sum = inv(factorial[count - k]) * sum % MOD;
            answer = (answer + sum) % MOD;
        }

        output.push(answer.toString());
    }

    console.log(output.join('\n'));
}

